fn weakestLeaf(t: *const Tree, n: *Node, best: *?*Node, in: ?LeafFilter) void {
    if (n.parent != null and n.kids.items.len == 0 and n.pins == 0 and t.idle(n) and
        (in == null or (n.pages.len > 0 and in.?.f(in.?.ctx, n.pages[0]))) and
        (best.* == null or lessValuable(n, best.*.?))) best.* = n;
    for (n.kids.items) |k| t.weakestLeaf(k, best, in);
